    function ocr_splitTextIntoChunks(text2, maxChunkSize = 3e3) {
      const chunks2 = [];
      let startPos = 0;
      console.log(`[OCR] Splitting ${text2.length} characters into chunks of max ${maxChunkSize}`);
      while (startPos < text2.length) {
        let endPos = startPos + maxChunkSize;
        if (endPos >= text2.length) {
          const finalChunk = text2.substring(startPos).trim();
          if (finalChunk.length > 0) {
            chunks2.push(finalChunk);
            console.log(
              `[OCR] Chunk ${chunks2.length}: ${startPos} to end (${finalChunk.length} chars)`
            );
          }
          break;
        }
        const searchText = text2.substring(startPos, endPos);
        let bestBreak = -1;
        for (let i2 = searchText.length - 1; i2 >= Math.floor(searchText.length * 0.7); i2--) {
          const char = searchText[i2];
          const nextChar = searchText[i2 + 1];
          if (char === "." && (nextChar === " " || nextChar === "\n" || i2 === searchText.length - 1)) {
            bestBreak = i2 + 1;
            break;
          }
        }
        if (bestBreak > 0) {
          endPos = startPos + bestBreak;
        }
        const chunk = text2.substring(startPos, endPos).trim();
        if (chunk.length > 0) {
          chunks2.push(chunk);
          console.log(`[OCR] Chunk ${chunks2.length}: ${startPos} to ${endPos} (${chunk.length} chars)`);
        }
        startPos = endPos;
        while (startPos < text2.length && /\s/.test(text2[startPos])) {
          startPos++;
        }
      }
      console.log(`[OCR] Successfully split into ${chunks2.length} chunks`);
      for (let i2 = 1; i2 < chunks2.length; i2++) {
        const prevEnd = chunks2[i2 - 1].substring(Math.max(0, chunks2[i2 - 1].length - 50));
        const currStart = chunks2[i2].substring(0, Math.min(50, chunks2[i2].length));
        if (prevEnd.includes(currStart.substring(0, 20)) || currStart.includes(prevEnd.substring(prevEnd.length - 20))) {
          console.warn(`[OCR] Possible overlap detected between chunks ${i2} and ${i2 + 1}`);
        }
      }
      return chunks2;
    }
